const fs = require('fs');
const path = require('path');
const input = $json;
const sourceDir = path.join(input.tender_root, '01_Source_Docs');
const files = fs.readdirSync(sourceDir).filter(f => !f.startsWith('.'));
return files.map(f => ({ json: { ...input, file: f, source_path: path.join(sourceDir, f) } }));

